const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// --- Helper Functions ---

/**
 * Masks clouds, shadows, and snow in Sentinel-2 L2A images using the SCL band.
 * @param {ee.Image} image The Sentinel-2 L2A image.
 * @return {ee.Image} The masked image.
 */
const maskS2L2A = (image) => {
  const scl = image.select('SCL');
  // Keep 'vegetation' (4), 'not vegetated' (5), and 'water' (6).
  const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(6));
  return image.updateMask(mask).divide(10000); // Normalize to 0-1 reflectance
};

/**
 * Creates a binary mask for "yellow" pixels.
 * Yellow is defined as high Red and Green, low Blue, with Red and Green being similar.
 * Thresholds are based on normalized surface reflectance (0-1).
 * @param {ee.Image} image The cloud-masked and normalized image.
 * @return {ee.Image} A binary image where 1 represents a yellow pixel.
 */
const createYellowMask = (image) => {
  const red = image.select('B4');
  const green = image.select('B3');
  const blue =image.select('B2');
  const yellowMask = red.gt(0.15)
                      .and(green.gt(0.15))
                      .and(blue.lt(0.1))
                      .and(red.subtract(green).abs().lt(0.05));
  return yellowMask.rename('yellow_pixels');
};

/**
 * Processes an ImageCollection to count total and yellow pixels.
 * @param {ee.ImageCollection} collection The collection to process.
 * @param {ee.Geometry} geometry The region of interest.
 * @param {number} scale The scale for reduction.
 * @return {ee.Dictionary} A dictionary with 'total' and 'yellow' pixel counts.
 */
const countYellowPixels = (collection, geometry, scale) => {
  const maskedMosaic = collection.map(maskS2L2A).mosaic();
  const yellowImage = createYellowMask(maskedMosaic);

  const stats = yellowImage.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 4
  });
  return stats;
};


// --- Main Analysis Function ---

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon([[
    [19.0, 67.5], [19.0, 69.0], [23.5, 69.0], [23.5, 67.5]
  ]]); // Northern Lapland, Sweden

  const dateOct10 = ee.DateRange('2016-10-10', '2016-10-11');
  const dateSep = ee.DateRange('2016-09-01', '2016-09-30');
  const scale = 3000; // Use a large scale to avoid timeouts over the large area.

  // 2. Data Acquisition
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR');

  const colOct = s2Collection.filterBounds(geometry).filterDate(dateOct10);
  const colSep = s2Collection.filterBounds(geometry).filterDate(dateSep);

  // 3. Data Availability Check
  const countOct = colOct.size().getInfo();
  const countSep = colSep.size().getInfo();

  if (countOct === 0 || countSep === 0) {
    console.log(`Image count Oct 10 2016: ${countOct}`);
    console.log(`Image count Sep 2016: ${countSep}`);
    console.log("Evidence: One or both periods have no images available.");
    console.log("C1");
    return;
  }
  console.log(`Image count Oct 10 2016: ${countOct}`);
  console.log(`Image count Sep 2016: ${countSep}`);

  // 4. Processing and Calculation
  const statsOctServer = countYellowPixels(colOct, geometry, scale);
  const statsSepServer = countYellowPixels(colSep, geometry, scale);

  const statsOct = statsOctServer.getInfo();
  const statsSep = statsSepServer.getInfo();

  // 5. Validation & Final Answer
  const validPixelsOct = statsOct.yellow_pixels_count || 0;
  const validPixelsSep = statsSep.yellow_pixels_count || 0;

  if (validPixelsOct === 0 || validPixelsSep === 0) {
    console.log(`Valid (non-cloud) pixels on Oct 10: ${validPixelsOct}`);
    console.log(`Valid (non-cloud) pixels in Sep: ${validPixelsSep}`);
    console.log("Evidence: After cloud masking, no valid pixels remained for comparison.");
    console.log("C2");
    return;
  }

  const yellowPixelsOct = statsOct.yellow_pixels_sum || 0;
  const yellowPixelsSep = statsSep.yellow_pixels_sum || 0;

  // Calculate percentage of yellow area to account for different cloud cover
  const pctYellowOct = (yellowPixelsOct / validPixelsOct) * 100;
  const pctYellowSep = (yellowPixelsSep / validPixelsSep) * 100;

  console.log(`Valid pixel count on Oct 10: ${validPixelsOct}`);
  console.log(`Yellow pixel count on Oct 10: ${yellowPixelsOct}`);
  console.log(`Percentage of yellow area on Oct 10: ${pctYellowOct.toFixed(4)}%`);

  console.log(`Valid pixel count in Sep: ${validPixelsSep}`);
  console.log(`Yellow pixel count in Sep: ${yellowPixelsSep}`);
  console.log(`Percentage of yellow area in Sep: ${pctYellowSep.toFixed(4)}%`);

  if (pctYellowOct > pctYellowSep) {
    console.log("A");
  } else {
    console.log("B");
  }
}

// --- GEE Initialization and Execution ---

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error during analysis: ${e}`);
    console.log("D");
  }
}

initEE();
